<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {toast} from '../../utils/format';const id=ref(0),score=ref(5),content=ref(''),tags=ref<string[]>([]);onLoad(q=>id.value=Number(q?.id));const {busy,action}=usePage(async()=>{});function toggle(t:string){tags.value=tags.value.includes(t)?tags.value.filter(x=>x!==t):[...tags.value,t]}async function submit(){if(!content.value.trim())return toast('请写下这次服务的感受');await request('/orders/'+id.value+'/review','POST',{score:score.value,tags:tags.value,content:content.value});uni.navigateBack()}
</script><template><PageShell title="评价喂养师" back><view style="text-align:center;padding:24px 0"><view class="empty-icon">♡</view><view class="title">谢谢你，认真照顾它。</view><view class="subtitle">你的真实反馈，会让下一次更好。</view></view><view class="card"><view class="rating" style="text-align:center"><text v-for="n in 5" :key="n" @click="score=n">{{n<=score?'★':'☆'}}</text></view><view class="tabs" style="flex-wrap:wrap;margin-top:20px"><view v-for="t in ['准时到达','认真负责','反馈及时','很有耐心','清洁细致']" :key="t" :class="['tab',{active:tags.includes(t)}]" @click="toggle(t)">{{t}}</view></view><view class="field field-area"><textarea v-model="content" maxlength="1000" placeholder="分享本次上门照护的感受…"/></view><button class="primary" :loading="busy" :disabled="busy" @click="action(submit,'评价已提交')">提交评价</button></view></PageShell></template>
